import json

parsed = json.loads(root_files)
entries = parsed["entries"]

target_dirs = ["data", "docs", "config", "scripts"]
grouped = {d: [] for d in target_dirs}

for entry in entries:
    path = entry["path"]
    for d in target_dirs:
        prefix = f"/workspace/workspace/{d}/"
        if path.startswith(prefix):
            grouped[d].append({"name": entry["name"], "size": entry["size_bytes"]})

for d in target_dirs:
    print(f"\n📁 workspace/{d}/")
    if grouped[d]:
        for f in grouped[d]:
            print(f"   • {f['name']}  ({f['size']:,} bytes)")
    else:
        print("   (empty)")
